def known(locale, text, prefix):
    key = SOURCE_MESSAGES.get(str(text))
    return locale.msg(key) if key and key.startswith(prefix) else str(text)

def diagnostic(locale, value):
    text = str(value)
    key = SOURCE_MESSAGES.get(text)
    if key and (key.startswith("error.") or key.startswith("studio.")):
        return locale.msg(key)
    return locale.msg("common.details") + ": " + text

def activity(locale, value):
    key = SOURCE_MESSAGES.get(value)
    if key and key.startswith("event."):
        return locale.text(key)
    match = re.fullmatch(r"AI worker · ([A-Z_]+)(?: · ([\s\S]*))?", value)
    if match:
        state, detail = match.groups()
        key = {"AWAITING_REVIEW": "review"}.get(state, state.lower())
        translated = locale.text("work." + key) if "work." + key in locale.english else state
        return locale.text("event.worker", status=translated) + (" · " + str(diagnostic(locale, detail)) if detail else "")
    match = re.fullmatch(r"ChromaNeuroAI · Publicering: ([^\r\n]+)", value)
    if match:
        return locale.text("event.publication", status=known(locale, match[1], "publication."))
    return value

def ledger(locale, state):
    def render():
        s = state.snapshot
        status_key = "status." + state.status().lower()
        status = locale.text(status_key) if status_key in locale.english else state.status()
        label = locale.text
        n = locale.number
        if not s:
            return " | ".join(["ChromaPoints: —"] + [label(k) + ": —" for k in (
                "ledger.contribution", "ledger.consumption", "ledger.balance", "ledger.ratio")] + [status])
        a, p = s["account"], s["policy"]
        m = a["contribution"]
        first = " | ".join(label(k) + ": " + n(int(v) / 1e6) for k, v in (
            ("ledger.earned", a["earned"]), ("ledger.spent", a["spent"]),
            ("ledger.adjustments", s.get("adjustment", 0)), ("ledger.debt", s.get("debt", 0)),
            ("ledger.balance", s["available"])))
        first += " (" + label("ledger.includes", amount=n(int(a["bootstrap"]) / 1e6)) + ")"
        second = (label("ledger.data") + ": " + n(int(m["dataBytes"]), 0) + " B | CPU: " +
                  n(int(m["cpuMicros"]) / 1e6, 3) + " s | RAM: " +
                  n(int(m["ramByteMicros"]) / 1e6, 0) + " " + label("ledger.bytesec") +
                  " | GPU: " + n(int(m["gpuMicros"]) / 1e6, 3) + " s")
        third = (label("ledger.consumed") + ": " + n(int(a["consumedBytes"]), 0) +
                 " B | " + label("ledger.ratio.current") + ": 1:" + n(int(p["ratioBps"]) / 10000, 4) +
                 " | " + label("ledger.epoch") + " " + str(p["epoch"]) + " | " + status)
        return "\n".join((first, second, third)) + ("\n" + str(diagnostic(locale, state.error)) if state.error else "")
    return Message(render)

def target_description(locale, target):
    return target["id"] + "\n\n" + "\n\n".join(
        str(known(locale, label, "target.")) + ":\n" + str(known(locale, target.get(key, default), "target."))
        for key, label, default in FIELDS)
